#include <SPI.h>

const int chipSelect = 10;

void setup() {
    // Inicializa el controlador SPI de hardware
    SPI.begin();

    // Configura el pin CS/SS como salida
    pinMode(chipSelect, OUTPUT);
    digitalWrite(chipSelect, HIGH);
}

void loop() {
    // Selecciona el dispositivo esclavo (Nivel BAJO)
    digitalWrite(chipSelect, LOW);

    // Transfiere un byte de datos (ej. valor 10)
    SPI.transfer(10);

    // Deselecciona el dispositivo (Nivel ALTO)
    digitalWrite(chipSelect, HIGH);

    delay(1000);
}
